            return Long.bitCount(chosen);
        }

        // Check if sets[idx] is already hit
        if ((sets[idx] & chosen) != 0) {
            return dfs(sets, idx + 1, chosen);
        }

        // Need to pick at least one element from sets[idx]
        int best = Integer.MAX_VALUE;
        long mask = sets[idx];
        while (mask != 0) {
            long bit = mask & (-mask);
            mask -= bit;
            int candidate = dfs(sets, idx + 1, chosen | bit);
            if (candidate < best) {
                best = candidate;
            }
        }
        return best;
    }
